package platform
import("errors";"net";"net/url";"os";"regexp";"strings")
type Config struct{Addr,PublicURL,Issuer,ClientID,ClientSecret,DatabaseURL,WebDir,CommitSHA string}
func ReadSecret(path string)(string,error){if path==""{return "",errors.New("required secret FILE path missing")};f,e:=os.Open(path);if e!=nil{return "",errors.New("secret file cannot be opened")};defer f.Close();st,e:=f.Stat();if e!=nil||!st.Mode().IsRegular()||st.Mode().Perm()&0077!=0||st.Size()>16384{return "",errors.New("secret file must be regular, private (0600 or stricter), <=16KiB")};b:=make([]byte,st.Size());n,e:=f.Read(b);if e!=nil||int64(n)!=st.Size(){return "",errors.New("secret file cannot be read")};v:=strings.TrimSpace(string(b));if v==""{return "",errors.New("secret file empty")};return v,nil}
func DatabaseURL()(string,error){for _,k:=range []string{"MB_DATABASE_URL","PGPASSWORD","MB_DATABASE_PASSWORD","MB_OIDC_CLIENT_SECRET"}{if os.Getenv(k)!=""{return "",errors.New("raw secret environment variables forbidden; use FILE paths")}};return ReadSecret(os.Getenv("MB_DATABASE_URL_FILE"))}
func Load(buildSHA string)(Config,error){c:=Config{Addr:os.Getenv("MB_HTTP_ADDR"),PublicURL:strings.TrimRight(os.Getenv("MB_PUBLIC_URL"),"/"),Issuer:os.Getenv("MB_OIDC_ISSUER"),ClientID:os.Getenv("MB_OIDC_CLIENT_ID"),WebDir:os.Getenv("MB_WEB_DIR"),CommitSHA:buildSHA};if c.Addr==""{c.Addr="127.0.0.1:12023"};if c.WebDir==""{c.WebDir="web/dist"};if v:=os.Getenv("MB_COMMIT_SHA");v!=""{c.CommitSHA=v};if !regexp.MustCompile(`^[0-9a-f]{40}$`).MatchString(c.CommitSHA){return c,errors.New("exact 40-character lowercase commit SHA required")}
 host,_,e:=net.SplitHostPort(c.Addr);ip:=net.ParseIP(host);if e!=nil||ip==nil||!ip.IsLoopback(){return c,errors.New("MB_HTTP_ADDR must bind loopback")}
 for _,s:=range []string{c.PublicURL,c.Issuer}{u,e:=url.Parse(s);if e!=nil||u.Scheme!="https"||u.Hostname()==""||u.User!=nil||u.RawQuery!=""||u.Fragment!=""{return c,errors.New("public URL and OIDC issuer must be explicit HTTPS URLs")}}
 u,_:=url.Parse(c.PublicURL);if u.Path!=""{return c,errors.New("MB_PUBLIC_URL must be an origin without a path")};if c.ClientID==""{return c,errors.New("MB_OIDC_CLIENT_ID required")};if c.DatabaseURL,e=DatabaseURL();e!=nil{return c,e};if c.ClientSecret,e=ReadSecret(os.Getenv("MB_OIDC_CLIENT_SECRET_FILE"));e!=nil{return c,e};return c,nil}
